    DISLIKE,
    INDIFFERENT;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeFfiLikeStatus: FfiConverterRustBuffer<FfiLikeStatus> {
    override fun read(buf: ByteBuffer) = try {
        FfiLikeStatus.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: FfiLikeStatus) = 4UL

    override fun write(value: FfiLikeStatus, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







