        val `msg`: kotlin.String
        ) : MediyoException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MediyoException> {
        override fun lift(error_buf: RustBuffer.ByValue): MediyoException = FfiConverterTypeMediyoError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeMediyoError : FfiConverterRustBuffer<MediyoException> {
    override fun read(buf: ByteBuffer): MediyoException {
        

        return when(buf.getInt()) {
            1 -> MediyoException.Api(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MediyoException): ULong {
        return when(value) {
            is MediyoException.Api -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: MediyoException, buf: ByteBuffer) {
        when(value) {
            is MediyoException.Api -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




